from functools import wraps
from ..pylogger.logger import log_suppression


def force_reconnect_while_not_connected(func):
    @wraps(func)
    def interface_func(*args, **kwargs):
        self = args[0]

        if not self.is_connected():
            log_suppression("Surprisingly Your device connection (with alias: {0}) was dead. Force reconnecting...".
                            format(self.get_alias()))
            self.force_reconnect()

        outcome = func(*args, **kwargs)

        return outcome

    return interface_func
